let arenaResources=null, arenaWarmPromise=null, arenaReady=false;
const compiledRenderers=new WeakSet();
const swingSide=swing=>swing.direction==='left'?-1:1;
const clamp01=value=>Math.max(0,Math.min(1,value));
const initialArenaTimeOfDay=preferences.timeOfDay==='random'?(Math.random()<.5?'day':'evening'):preferences.timeOfDay;
export function warmGameArena(){
  if(arenaWarmPromise)return arenaWarmPromise;
  const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(preferences.fov,innerWidth/innerHeight,.05,280),renderer=new THREE.WebGLRenderer({antialias:true});
  renderer.domElement.style.cssText='position:fixed;left:-10000px;top:0;visibility:hidden';renderer.setPixelRatio(Math.min(devicePixelRatio,('ontouchstart'in window||navigator.maxTouchPoints>0)?1.5:2));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
  const world=createArena(scene,renderer,{timeOfDay:initialArenaTimeOfDay});scene.add(camera);
  const warmViewLight=new THREE.PointLight(0xffe4b5,0,2.4);warmViewLight.position.set(.2,-.1,-.8);camera.add(warmViewLight);
  const viewGlow=new THREE.PointLight(0x22d3ee,0,1.6);viewGlow.position.set(0,-.25,-.72);camera.add(viewGlow);
  const opponentLights=new THREE.Group();opponentLights.name='opponentLights';
  const opponentRim=new THREE.PointLight(0xef4444,0,8);opponentRim.position.y=1.2;
  const warmRim=new THREE.PointLight(0xffe4b5,0,6);warmRim.position.set(-.8,2.2,-.5);
  const opponentGlow=new THREE.PointLight(0xa855f7,0,3);opponentGlow.position.y=1.2;
  const opponentSpecialGlow=new THREE.PointLight(0x22d3ee,0,4);opponentSpecialGlow.position.y=1.2;
  opponentLights.add(opponentRim,warmRim,opponentGlow,opponentSpecialGlow);scene.add(opponentLights);
  const baseChildren=new Set(scene.children);arenaResources={scene,camera,renderer,world,baseChildren,warmViewLight,viewGlow,opponentLights,opponentRim,warmRim,opponentGlow,opponentSpecialGlow};
  arenaWarmPromise=warmArenaAtmosphere(world,scene,renderer,camera).then(()=>{renderer.render(scene,camera);renderer.domElement.style.visibility='hidden';arenaReady=true;return arenaResources;}).catch(error=>{console.warn('Arena warm-up failed',error);arenaReady=true;return arenaResources;});
  return arenaWarmPromise;
}

export async function warmGameAssets(fighters=[]){
  const resources=await warmGameArena();if(!resources||compiledRenderers.has(resources.renderer))return;
  const [models,props]=await Promise.all([Promise.all(fighters.map(async name=>({name,model:await loadFighter(name)}))),Promise.all(['sword_1handed.gltf','shield_round.gltf'].map(loadProp))]);
  const propsGroup=new THREE.Group();props.forEach((prop,index)=>{prop.position.set(index*.5,0,0);propsGroup.add(prop);});resources.scene.add(propsGroup);
  const positioned=[];
  try{
    for(const {name,model} of models){addFresnelRim(model);const root=model.root,parent=root.parent,pos=root.position.clone(),rot=root.rotation.clone();positioned.push({name,model,root,parent,pos,rot});resources.scene.add(root);root.position.set(positioned.length*2,0,-10);root.visible=true;}
    await resources.renderer.compileAsync(resources.scene,resources.camera);
    resources.renderer.render(resources.scene,resources.camera);compiledRenderers.add(resources.renderer);
  }finally{
    resources.scene.remove(propsGroup);
    for(const entry of positioned){resources.scene.remove(entry.root);entry.root.position.copy(entry.pos);entry.root.rotation.copy(entry.rot);}
  }
}

